    fn load_returns_none_on_content_metadata_size_mismatch() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store.store("http:test", "t1", "hello", 3600).unwrap();

        // Simulate corruption: overwrite content with different-length data
        fs::write(&entry.content_path, "this content has a different length").unwrap();

        let loaded = store.load("http:test", "t1").unwrap();
        assert!(
            loaded.is_none(),
            "Should return None when content size doesn't match metadata"
        );
    }

