                        .store("http:test", "shared", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // Content file must be valid (all same character)
        let content_path = store.content_path("http:test", "shared");
        let content = fs::read_to_string(&content_path).unwrap();
        assert!(
            content.chars().all(|c| c == 'x'),
            "Content file is corrupt: contains non-x characters"
        );
        assert!(
            content.len() % 1000 == 0 && content.len() >= 1000 && content.len() <= 10000,
            "Content length {} is not a valid multiple of 1000",
            content.len()
        );

        // Metadata file must be valid JSON
        let meta_path = content_path.with_extension("meta.json");
        let json = fs::read_to_string(&meta_path).unwrap();
        let entry: CacheEntry = serde_json::from_str(&json).unwrap();
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared");
    }
