}

/// Write a file atomically using a temp-file-then-rename strategy.
///
/// Writes content to a temporary file in the same directory, then
/// renames it to the target path. This prevents readers from ever
/// seeing partially-written content, even under concurrent access
/// from multiple processes.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let mut tmp_name = path.as_os_str().to_os_string();
    tmp_name.push(format!(".tmp.{}", std::process::id()));
    let tmp_path = PathBuf::from(tmp_name);

    fs::write(&tmp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", tmp_path))?;

    if let Err(e) = fs::rename(&tmp_path, path) {
        let _ = fs::remove_file(&tmp_path);
        return Err(e)
            .with_context(|| format!("Failed to rename {:?} to {:?}", tmp_path, path));
    }

    Ok(())
}

/// Store content and return a cache entry.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    self.ensure_dir()?;

    let content_path = self.content_path(source_id, template_name);
    Self::atomic_write(&content_path, content.as_bytes())?;

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);

    self.save_metadata(&entry)?;

    Ok(entry)
}

