mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn cache_store_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        assert_eq!(store.root(), temp.path());
    }

    #[test]
    fn store_and_load() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "template content", 3600)
            .unwrap();

        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "template1");

        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.source_id, entry.source_id);
        assert_eq!(loaded.template_name, entry.template_name);
    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn load_returns_none_on_content_metadata_size_mismatch() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store.store("http:test", "t1", "hello", 3600).unwrap();

        // Simulate corruption: overwrite content with different-length data
        fs::write(&entry.content_path, "this content has a different length").unwrap();

        let loaded = store.load("http:test", "t1").unwrap();
        assert!(
            loaded.is_none(),
            "Should return None when content size doesn't match metadata"
        );
    }

    #[test]
    fn load_returns_none_when_content_file_missing() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store.store("http:test", "t1", "hello", 3600).unwrap();

        // Remove just the content file, leaving metadata orphaned
        fs::remove_file(&entry.content_path).unwrap();

        let loaded = store.load("http:test", "t1").unwrap();
        assert!(
            loaded.is_none(),
            "Should return None when content file is missing"
        );
    }

    #[test]
    fn write_content_produces_readable_file() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "initial", 3600).unwrap();
        store.write_content("http:test", "t1", "updated").unwrap();

        let content_path = store.content_path("http:test", "t1");
        let content = fs::read_to_string(content_path).unwrap();
        assert_eq!(content, "updated");
    }

    #[test]
    fn no_temp_files_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "content1", 3600).unwrap();
        store.store("http:test", "t2", "content2", 3600).unwrap();

        for entry in fs::read_dir(temp.path()).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy();
            assert!(
                !name.contains(".tmp."),
                "Temp file should not remain: {}",
                name
            );
        }
    }

    #[test]
    fn concurrent_stores_never_corrupt_files() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));
        let thread_count = 10;
        let barrier = Arc::new(Barrier::new(thread_count));

        let handles: Vec<_> = (0..thread_count)
            .map(|i| {
                let store = Arc::clone(&store);
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || {
                    barrier.wait();
                    let content = "x".repeat(1000 * (i + 1));
                    store
                        .store("http:test", "shared", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // Content file must be valid (all same character)
        let content_path = store.content_path("http:test", "shared");
        let content = fs::read_to_string(&content_path).unwrap();
        assert!(
            content.chars().all(|c| c == 'x'),
            "Content file is corrupt: contains non-x characters"
        );
        assert!(
            content.len() % 1000 == 0 && content.len() >= 1000 && content.len() <= 10000,
            "Content length {} is not a valid multiple of 1000",
            content.len()
        );

        // Metadata file must be valid JSON
        let meta_path = content_path.with_extension("meta.json");
        let json = fs::read_to_string(&meta_path).unwrap();
        let entry: CacheEntry = serde_json::from_str(&json).unwrap();
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared");
    }
}

